{
["recordedBy"] = "Simonpriest-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Walton",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Walton says: Sorry if they roughed you up, Vrang. If I had known they got you, I'd have come running.",
["id"] = "s4_3602",
["timestamp"] = 1795216677,
},
{
["recordedBy"] = "Simonpriest-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Vrang Wildgore",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Vrang Wildgore says: Is it true--you deserted your brothers in arms?",
["id"] = "s4_3603",
["timestamp"] = 1795216683,
},
{
["recordedBy"] = "Simonpriest-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Walton",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
